import { renderReviewItem, renderReportEvidence, reviewFieldLabel, displayedReviewValue } from './db-review.js';
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const date = value => value ? new Date(value).toLocaleString('ko-KR', { timeZone: 'Asia/Seoul' }) : '접수 시각 미기록';
const labels = { all: '전체', needs_review: '내용 확인 필요', ready: 'DB 등록 준비됨', partial: '일부 등록', published: 'DB 등록 완료', excluded: '제외됨' };
const findingLabels = { ...labels, published_previous_review: '이전 검토로 등록됨', conflict: '기등록 사례와 불일치', stored_awaiting_receipt: '등록 확인 기록 대기', registered_incomplete: 'DB 등록됨 · 재현 정보 보완 필요', registered_previous_review: '이전 검토 내용으로 DB 등록됨' };
function steps(current) {
  return `<ol class="intake-steps" aria-label="보고서 처리 순서">${['보고서 올리기', '읽어온 내용 확인', '취약점 DB에 등록'].map((label, i) => `<li class="${i + 1 === current ? 'current' : i + 1 < current ? 'done' : ''}"${i + 1 === current ? ' aria-current="step"' : ''}><span>${i + 1 < current ? '✓' : i + 1}</span>${label}</li>`).join('')}</ol>`;
}
export function renderIntakes(db, canEdit) {
  return `<section class="panel ops-panel intake-intro"><div class="eyebrow">보고서로 취약점 자료 만들기</div><h2>한글 보고서에서 취약점 정보를 가져옵니다</h2><p>문서의 본문·표·이미지에서 정보를 읽고, 확인한 항목을 다음 점검에 참고할 취약점 기록으로 저장합니다.</p>${steps(1)}${db.uploadConflict ? `<div class="intake-feedback" role="alert"><strong>이미 올린 보고서입니다.</strong><p>이 파일은 원래 대상 <b>${escape(db.uploadConflict.existingTargetId)}</b>에 연결되어 있습니다. 다른 사이트에 참고하기 위해 원본 보고서의 대상을 바꿀 필요는 없습니다.</p>${db.uploadConflict.existingDraftSha ? '<button class="button primary" data-action="open-existing-intake">기존 보고서 열기</button>' : ''} <button class="button secondary" data-action="use-existing-target">원래 대상 이름 사용</button></div>` : ''}
    <form id="intake-upload-form" class="ops-upload-form"><label>이 보고서에서 원래 점검한 사이트·서비스는 어디인가요?<input id="intake-target-id" required pattern="[A-Za-z0-9][A-Za-z0-9._-]{0,63}" list="intake-targets" placeholder="예: vul-web2-daehan" value="${escape(db.uploadTarget || '')}"><small>새로 점검할 사이트가 아니라 이 보고서의 원래 대상을 입력합니다. 영문·숫자·점·밑줄·하이픈을 사용하세요.</small></label><datalist id="intake-targets"><option value="vul-web2-daehan">대한대학교 실습</option><option value="vul-web2-wonchang">원창대학교 실습</option><option value="vul-web-1">로컬 게시판</option></datalist>
    <div class="ops-dropzone" id="intake-dropzone" tabindex="0"><strong>읽을 HWP / HWPX 파일을 선택하세요</strong><small>여기에 파일을 놓아도 됩니다 · 최대 32 MB</small><input id="intake-file" type="file" accept=".hwp,.hwpx"${db.selectedFile ? '' : ' required'}><span id="intake-file-name">${escape(db.selectedFile?.name || '선택한 파일이 없습니다')}</span></div>
    <div class="intake-ocr-options"><label><input id="intake-ocr" type="checkbox" ${db.ocrEnabled ? 'checked' : ''}> 스크린샷·이미지 안의 글자도 읽기</label><small>캡처 이미지에 재현 과정이나 시험 문자열이 들어 있다면 선택하세요. 서버의 로컬 OCR을 사용합니다.</small><label>이미지의 언어<select id="intake-ocr-language">${[['ko', '한국어'], ['en', '영어'], ['kor+eng', '한국어 + 영어'], ['kor', '한국어 (kor)'], ['eng', '영어 (eng)']].map(([value, label]) => `<option value="${value}"${db.ocrLanguage === value ? ' selected' : ''}>${label}</option>`).join('')}</select></label></div>
    <details class="intake-optional-analysis"><summary>선택 기능 · 로컬 모델로 추가 분석</summary><label><input id="intake-local-llm" type="checkbox" ${db.localLlmEnabled ? 'checked' : ''} ${canEdit ? '' : 'disabled'}> 로컬 LLM으로 문맥을 읽고 원문과 대조</label><small>기본 처리는 문서 읽기·추출 규칙·OCR입니다. 문맥 분석이 추가로 필요할 때만 선택하세요. 외부 API는 사용하지 않습니다. ${db.health?.localLlm?.available ? escape(db.health.localLlm.model) : 'Modules → DB에서 로컬 모델 연결을 확인하세요.'}</small></details>
    <button class="button primary" type="submit" ${canEdit && !db.loading ? '' : 'disabled'}>${db.uploading ? '보고서 내용을 읽고 있습니다…' : '파일 올리고 내용 읽기'}</button>${db.uploading ? '<p role="status">파일을 보관하고 본문·표에서 취약점 후보를 찾고 있습니다. 이미지 읽기를 선택하면 시간이 더 걸릴 수 있습니다. 완료되면 확인할 내용이 열립니다.</p>' : '<small>이 단계에서는 원본과 추출 결과를 보관합니다. 확인 전에는 취약점 DB에 등록하지 않습니다.</small>'}</form></section>
    <section class="panel ops-panel"><div class="ops-panel-head"><h2>올린 보고서 ${db.intakeTotal}개</h2><button class="button secondary" data-action="refresh-db">목록 새로고침</button></div>
    <form id="intake-search-form" class="ops-filters"><label>파일명·대상 검색<input id="intake-query" type="search" value="${escape(db.intakeQuery)}"></label><label>처리 상태<select id="intake-status">${Object.entries(labels).map(([value, label]) => `<option value="${value}"${db.intakeStatus === value ? ' selected' : ''}>${label}</option>`).join('')}</select></label><label>정렬<select id="intake-sort">${[['newest', '최근 접수순'], ['oldest', '오래된 접수순'], ['filename', '파일명순']].map(([value, label]) => `<option value="${value}"${db.intakeSort === value ? ' selected' : ''}>${label}</option>`).join('')}</select></label><button class="button secondary" type="submit">조회</button></form>
    <div class="ops-list">${db.intakes.map(item => `<button class="ops-row" data-intake-id="${escape(item.draft_sha256)}"><span><strong>${escape(item.source_filename)}</strong><small>${escape(item.target_id)} · ${escape(date(item.received_at))}</small><small>찾은 항목 ${item.finding_count ?? item.findings?.length ?? 0}건 · DB 등록 ${item.counts?.published || 0}건 · 내용 확인 필요 ${item.counts?.needs_review || 0}건</small></span><span class="state-chip">${escape(labels[item.status] || '내용 확인 필요')} →</span></button>`).join('') || '<div class="ops-empty">아직 올린 보고서가 없습니다. 위에서 파일을 선택해 시작하세요.</div>'}</div>
    <div class="ops-pagination"><button class="button secondary" data-action="intake-prev" ${db.intakeOffset <= 0 ? 'disabled' : ''}>이전</button><span>${db.intakeTotal ? db.intakeOffset + 1 : 0}–${Math.min(db.intakeTotal, db.intakeOffset + db.intakes.length)} / ${db.intakeTotal}</span><button class="button secondary" data-action="intake-next" ${db.intakeOffset + db.intakes.length >= db.intakeTotal ? 'disabled' : ''}>다음</button></div></section>`;
}
export function renderIntakeDetail(db, canEdit) {
  const intake = db.intakeDetail?.intake || db.intakeDetail;
  if (!intake) return '';
  const review = intake.review || {}, draft = intake.draft || {}, findings = draft.findings || [];
  const items = review.items || [], states = intake.findings || [], blocked = intake.validation?.blocked || [];
  const ready = states.filter(item => item.registration_eligible && !item.registration_current).length;
  const published = states.filter(item => item.registered_record || item.case_record).length;
  const done = published > 0 && states.every(item => item.registration_current || item.state === 'excluded');
  const registrationBlocked = states.filter(item => !item.registration_eligible && !item.registration_current && item.state !== 'excluded');
  const incomplete = states.filter(item => item.registration_eligible && !item.reproduction_ready).length;
  const reviewed = Boolean(review.reviewed_at);
  const allExcluded = !!states.length && states.every(item => item.state === 'excluded');
  const active = Math.min(db.reviewIndex || 0, Math.max(0, items.length - 1));
  const finalReview = db.reviewStep === 'register';
  return `<section class="panel ops-panel intake-detail"><button class="text-button" data-action="close-intake">← 올린 보고서 목록</button><h2>${escape(intake.source_filename || '올린 보고서')}</h2><p>${escape(intake.target_id)} · 문서에서 찾은 취약점 후보 ${findings.length}건 · DB에 등록된 기록 ${published}건</p>${steps(done ? 4 : finalReview ? 3 : 2)}
    <details class="intake-analysis"><summary>선택 기능 · 로컬 모델로 다시 분석</summary><strong>원문을 다시 읽어 필요한 정보를 추출</strong><p>기존 보고서와 검토는 유지하고 새 분석 결과를 만듭니다. 모델 결과에는 원문 근거와 대조 결과가 붙습니다.</p><button class="button secondary" data-action="analyze-local" ${canEdit && db.health?.localLlm?.available && !db.llmBusy ? '' : 'disabled'}>${db.llmBusy ? '로컬 모델이 원문과 이미지를 분석·대조하고 있습니다…' : '로컬 LLM으로 다시 분석·원문 대조'}</button>${draft.document?.local_llm ? `<p>분석 모델 ${escape(draft.document.local_llm.model)} · 원문 대조로 보존한 후보 ${(draft.document.local_llm.findings || []).reduce((n, f) => n + (f.accepted?.length || 0), 0)}개 · 보류 ${(draft.document.local_llm.findings || []).reduce((n, f) => n + (f.rejected?.length || 0), 0)}개 · 최종 검토 전</p>` : ''}</details>
    <dl class="intake-state-summary"><div><dt>보고서 파일</dt><dd>보관 완료</dd></div><div><dt>검토 내용</dt><dd>${reviewed ? '저장됨' : '아직 확인 전'}</dd></div><div><dt>취약점 DB</dt><dd>${published ? `${published}건 등록됨` : '아직 등록되지 않음'}</dd></div><div><dt>지금 등록 가능한 항목</dt><dd>${ready}건</dd></div></dl>
    ${db.intakeNotice ? `<p class="intake-feedback" role="status">${escape(db.intakeNotice)}</p>` : ''}
    <div class="intake-next"><strong>${done ? '이 보고서의 취약점 정보를 DB에 등록했습니다.' : allExcluded ? '모든 항목을 제외하여 DB에 등록할 내용이 없습니다.' : reviewed && !ready ? '검토 내용은 저장됐지만 DB 등록은 보류 중입니다.' : ready && !registrationBlocked.length ? `${ready}건을 DB에 등록할 준비가 됐습니다.` : findings.length ? '다음: 읽어온 내용을 원문과 비교해 확인하세요.' : '문서는 읽었지만 취약점 후보를 찾지 못했습니다.'}</strong><p>${done ? '다음 점검에서 참고할 기록으로 보관됩니다. 등록된 내용을 열어 확인할 수 있습니다.' : ready && !registrationBlocked.length ? '마지막 확인 화면에서 DB 등록을 누르면 취약점 기록으로 저장됩니다.' : findings.length ? '왼쪽 원문과 오른쪽 자동 입력 내용을 비교하고 확인하고 다음을 누르세요. 다시 입력할 필요는 없으며, 미확인 값과 여러 후보도 함께 보존되며, 재현에 필요한 정보는 등록 후 보완할 수 있습니다.' : '아래에서 읽힌 본문과 이미지를 확인하세요. 보고서 형식이나 항목명이 달라 추가 확인이 필요할 수 있습니다.'}</p>${done ? '<button class="button primary" data-action="view-intake-cases">등록된 취약점 보기</button>' : ''}</div>
    ${!finalReview && items.length ? `<div class="intake-guide"><strong>확인 ${active + 1} / ${items.length}</strong><p>자동으로 채운 내용을 보고 ‘확인하고 다음’을 누르세요. 마지막 ‘확인하고 DB에 등록’ 버튼을 누르면 자료가 바로 저장됩니다.</p><button type="button" class="button secondary" data-action="review-final">최종 등록 전 확인으로 이동</button></div>` : ''}
    ${finalReview ? `<section class="intake-final"><h3>최종 등록 전 확인</h3><p>등록 준비 ${ready}건 · 미검토 ${registrationBlocked.length}건 · 이미 등록 ${published}건</p>${items.map((item, index) => { const state = states.find(s => s.draft_id === item.draft_id); return `<div class="ops-row"><span><strong>${escape(findings.find(f => f.draft_id === item.draft_id)?.candidate?.title || `취약점 후보 ${index + 1}`)}</strong><small>${escape(findingLabels[state?.state] || '추가 확인 필요')}</small></span><button type="button" class="button secondary" data-goto-review="${index}">내용 다시 보기</button></div>`; }).join('')}</section>` : ''}
    ${finalReview && registrationBlocked.length ? `<section class="intake-blockers" aria-label="다음 단계로 가기 위해 필요한 확인"><h3>아래 항목은 아직 검토하지 않았습니다</h3><p>자료를 확인하고 다음을 누르거나 보류·제외를 선택하세요. 재현 정보가 부족하다는 이유로 DB 등록을 막지는 않습니다.</p>${items.map((item, index) => {
      const missing = blocked.find(b => b.draft_id === item.draft_id);
      if (!missing || !registrationBlocked.some(state => state.draft_id === item.draft_id)) return '';
      const finding = findings.find(f => f.draft_id === item.draft_id) || {};
      return `<div><strong>취약점 후보 ${index + 1}</strong>${item.decision === 'pending' ? `<button class="button secondary" data-goto-review="${index}" data-focus-decision>아직 확인하지 않은 항목 · 내용 보기</button>` : ''}<div class="intake-missing-links">${(missing.remaining_fields || []).filter(key => !['case_id','target_id','source_report','status','source'].includes(key)).map(key => `<button class="button secondary" data-goto-review="${index}" data-focus-field="${escape(key)}">${escape(reviewFieldLabel(key))}${displayedReviewValue(finding, item, key) ? ' 후보' : ''} 확인 →</button>`).join('')}</div></div>`;
    }).join('')}</section>` : ''}
    ${finalReview && incomplete ? `<p class="intake-feedback">재현 정보 보완 필요 ${incomplete}건도 DB에 등록할 수 있습니다. 미확인 값과 원문 후보를 보존하고, 재현 준비가 끝난 사례와 구분합니다.</p>` : ''}
    ${finalReview && ready && !done ? `<section class="intake-register"><h3>확인한 내용을 취약점 DB에 등록</h3><p>등록할 수 있는 항목 ${ready}건${registrationBlocked.length ? ` · 아직 확인이 필요한 항목 ${registrationBlocked.length}건` : ''}</p>${registrationBlocked.length ? '<label><input id="publish-ready-only" type="checkbox"> 확인이 끝난 항목만 등록하고 나머지는 보류합니다.</label>' : '<input id="publish-ready-only" type="checkbox" hidden>'}<button class="button primary" data-action="publish-intake" ${canEdit && !db.reviewDirty && !registrationBlocked.length ? '' : 'disabled'}>확인한 ${ready}건을 DB에 등록</button></section>` : ''}
    ${items.length ? `<nav class="intake-candidates" aria-label="확인할 취약점 선택">${items.map((item, i) => `<button data-review-select="${i}" aria-pressed="${i === active}">${i + 1}. ${escape(findings.find(f => f.draft_id === item.draft_id)?.candidate?.title || '취약점 후보')}</button>`).join('')}</nav>` : ''}
    <div class="intake-review-layout"${db.llmBusy ? ' inert aria-busy="true"' : ''}${finalReview ? ' hidden' : ''}><aside class="intake-evidence">${renderReportEvidence(draft, intake.imagePreviews || [])}</aside><div class="intake-editor"><form id="intake-review-form">${items.map((item, i) => `<div class="intake-candidate-panel" data-candidate-panel="${i}"${i !== active ? ' hidden' : ''}>${renderReviewItem(findings.find(f => f.draft_id === item.draft_id) || {}, item, i, { state: states.find(s => s.draft_id === item.draft_id), blocked: blocked.find(b => b.draft_id === item.draft_id) })}</div>`).join('')}${items.length ? `<div class="intake-save"><p id="intake-unsaved" role="status"${db.reviewDirty ? '' : ' hidden'}>수정한 내용이 있습니다. 먼저 확인 결과를 저장하세요.</p><div class="ops-form-actions"><button class="button primary" type="submit" value="confirm" data-review-next ${canEdit ? '' : 'disabled'}>${active + 1 < items.length ? '확인하고 다음' : '확인하고 DB에 등록'}</button><button class="button secondary" type="submit" value="defer" ${canEdit ? '' : 'disabled'}>보류하고 다음</button><button class="button secondary" type="submit" value="draft" ${canEdit ? '' : 'disabled'}>임시 저장</button></div><small>자동으로 채운 값은 다시 입력하지 않아도 됩니다. 마지막 확인 버튼으로 DB에 등록됩니다. 미확인 정보는 등록 후 보완할 수 있습니다.</small></div>` : ''}</form>

    <div class="ops-publication">${states.map(item => `<p data-finding-state="${escape(item.state)}">${escape(item.endpoint || '경로 확인 필요')} · ${escape(findingLabels[item.state] || item.state)}</p>`).join('')}</div></div></div>
    <details class="intake-technical"><summary>처리 기록·이전 추출 결과·고급 정보</summary>${intake.extractionVersions?.length > 1 ? `<label>추출 결과 선택<select id="intake-extraction-select">${intake.extractionVersions.map((version, i) => `<option value="${escape(version.draft_sha256)}"${version.draft_sha256 === intake.draft_sha256 ? ' selected' : ''}>${i + 1}. ${escape(version.draft_sha256.slice(0, 12))}</option>`).join('')}</select></label>` : ''}<pre>${escape(JSON.stringify({ draft: intake.draft_sha256, validation: intake.validation, audit: intake.audit }, null, 2))}</pre><button class="button secondary" data-action="delete-intake" ${canEdit ? '' : 'disabled'}>미등록 보고서 초안 삭제</button></details></section>`;
}
